import hmac
import secrets
import time

from flask import abort, current_app, flash, g, redirect, request, session, url_for

from .db import get_db


def now():
    """Current epoch seconds; module-level so tests can patch it."""
    return time.time()


def csrf_token():
    """Return the session's CSRF token, creating it lazily (also for anonymous visitors)."""
    if "csrf_token" not in session:
        session["csrf_token"] = secrets.token_urlsafe(32)
    return session["csrf_token"]


def _check_csrf():
    expected = session.get("csrf_token")
    supplied = request.form.get("csrf_token") or request.headers.get("X-CSRF-Token")
    if not expected or not supplied or not hmac.compare_digest(str(expected), str(supplied)):
        abort(400)


def before_request():
    if request.endpoint == "static":
        return None

    g.user = None
    user_id = session.get("user_id")
    if user_id is not None:
        timeout = current_app.config["SESSION_TIMEOUT_MINUTES"] * 60
        if now() - session.get("last_active", 0) > timeout:
            session.clear()
            if request.endpoint == "auth.keepalive":
                return "", 401
            flash("Your session expired. Please log in again.")
            return redirect(url_for("auth.login"))

        user = get_db().execute("SELECT id, username, email FROM user WHERE id = ?", (user_id,)).fetchone()
        if user is None:
            session.clear()
        else:
            g.user = user
            session["last_active"] = now()

    if request.method == "POST" and request.endpoint is not None:
        _check_csrf()
    return None


def after_request(response):
    if request.endpoint == "static":
        return response
    response.headers["Cache-Control"] = "no-store"
    response.headers["Content-Security-Policy"] = (
        "default-src 'self'; frame-ancestors 'none'; form-action 'self'; base-uri 'self'"
    )
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "same-origin"
    return response


def inject_template_globals():
    return {"csrf_token": csrf_token, "current_user": g.get("user")}


def init_app(app):
    app.before_request(before_request)
    app.after_request(after_request)
    app.context_processor(inject_template_globals)
